const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const studyStages=[
 {id:'start',title:"First, see what an operation does",prior:"No prerequisites",goal:"Distinguish an unchanged object, a fixed point, and the operation itself.",links:[["Six steps from the beginning",'classroom/start']]},
 {id:'foundations',title:"Build the language of representations",prior:"Reading coordinates and a simple matrix; both are introduced in the guide",goal:"Write matrices in a chosen basis, calculate characters, then use projection and reduction to identify subspaces.",links:[["Operations, point groups, and characters",'classroom/foundations?lesson=group-basics'],["D₃ projection and basis functions",'classroom/foundations?module=demos&experiment=projection'],["Theorem proofs and counterexamples",'classroom/foundations?module=theorems&experiment=rearrangement']]},
 {id:'branches',title:"Choose a branch for your question",prior:"Point groups and representations, followed by the physical concepts needed for each branch",goal:"Explore translations in crystals, time reversal in spin systems, or generators of continuous groups.",links:[["Crystals and space groups",'classroom/crystal'],["Spin, double groups, and magnetic groups",'classroom/spin'],["SU(2), SU(3), and generators",'classroom/continuous']]},
 {id:'applications',title:"Turn constraints into testable predictions",prior:"Representations, selection rules, and the relevant vibration or response concepts",goal:"Predict first, calculate and explain, then change one condition to test a counterexample.",links:[["Water and IR / Raman spectroscopy",'classroom/foundations?module=demos&experiment=water'],["Material properties and the SHG flagship experiment",'classroom/observables?module=shg-story'],["Phase transitions, diffraction, and imported data",'classroom/structure-dynamics']]},
 {id:'deeper',title:"Go deeper into proofs, coupling, and models",prior:"Complex matrices, quantum states, and the representation theory needed for your topic",goal:"Track conventions, outer multiplicities, conditions for protected degeneracy, and numerical checks.",links:[["Tensor products, CG, 6j, and 9j",'classroom/coupling'],["Symmetry derivation workshop",'classroom/crystal?module=workshop'],["Symmetry-adapted bases and matrix exercises",'classroom/foundations?module=salc']]},
 {id:'research',title:"Organize research records around a material",prior:"Explaining inputs, model assumptions, and validation errors",goal:"Connect lessons, tools, parameter comparisons, and material cases in a reproducible record.",links:[["All calculation tools",'compute'],["Groups and materials atlas",'atlas'],["Projects and guided assignments",'atlas/projects'],["Materials Research Record",'atlas/notebook']]}
];
export function studyMapHTML(){return `<details class="classroom-study-map" open><summary>Prerequisite and progression map · Choose a starting point based on what you know</summary><p>The map suggests a learning order; every lesson and tool remains directly accessible. Passing the introductory checks does not establish mastery of later research topics.</p><ol>${studyStages.map((stage,i)=>`<li><span class="study-stage-number">${String(i).padStart(2,'0')}</span><div><h3>${esc(stage.title)}</h3><p class="study-stage-prior">Suggested preparation:${esc(stage.prior)}</p><p>${esc(stage.goal)}</p><nav aria-label="${esc(stage.title)}">${stage.links.map(([title,route])=>`<a href="#${esc(route)}" data-course-route="#${esc(route)}">${esc(title)} →</a>`).join('')}</nav></div></li>`).join('')}</ol></details>`;}
